import { config } from './config.js';
export const escapeHtml = value => String(value).replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
export const icon = name => ({ arrow: '↗', right: '→', play: '▷', chevron: '⌄' })[name] || name;
export const button = (label, href, variant = 'primary', extra = '') => `<a class="button button--${variant}" href="${href}" ${extra}>${label}</a>`;
export const brand = (variant = 'default') => `<a href="#/" class="brand${variant === 'image' ? ' brand--image' : ''}" aria-label="${config.name} home">${variant === 'image' ? `<img src="${config.logo}" alt="${config.name}" width="2048" height="768">` : `<span class="brand-symbol" aria-hidden="true">♜</span><span>${config.name}<small>WRATH OF THE LICH KING</small></span>`}</a>`;
export function header(page) {
  const links = [['Home', ''], ['News', 'news'], ['Server', 'server'], ['Rankings', 'rankings'], ['How to play', 'play']];
  return `<header class="site-header"><div class="container header-inner"><div class="header-brand">${brand('image')}</div><button class="menu-toggle" aria-label="Open navigation" aria-controls="navigation" aria-expanded="false">☰</button><nav id="navigation" aria-label="Main navigation">${links.map(([label, path]) => `<a href="#/${path}" ${page === path ? 'aria-current="page"' : ''}>${label}</a>`).join('')}</nav><div class="header-actions"><a class="account-link" href="#/account">Account</a>${button('Play now', '#/play', 'ghost')}</div></div></header>`;
}
export const footer = () => `<footer class="site-footer"><div class="container footer-top">${brand()}<p>${config.description}<br>A realm worth coming home to.</p><nav aria-label="Footer"><a href="#/server">The realm</a><a href="#/rules">Realm rules</a><a href="#/account">Your account</a></nav></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} ${config.name}. An independent community project.</span><span>Not affiliated with Blizzard Entertainment.</span><span class="demo-label">Development preview · Demonstration content</span></div></footer>`;
export const pageHeader = (eyebrow, title, description) => `<section class="page-heading"><div class="container"><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="lead">${description}</p></div></section>`;
export const sectionHeader = (eyebrow, title, action = '') => `<div class="section-heading"><div><p class="eyebrow">${eyebrow}</p><h2>${title}</h2></div>${action}</div>`;
export const badge = text => `<span class="badge">${text}</span>`;
export const dateLabel = date => new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' }).format(new Date(`${date}T12:00:00Z`));
export const newsCard = article => `<article class="news-card"><a class="news-image" href="#/news/${article.id}" aria-label="Read ${escapeHtml(article.title)}"><img src="${article.image}" alt="${article.imageAlt}" loading="lazy"><span class="image-arrow" aria-hidden="true">↗</span></a><div class="news-meta">${badge(article.category)}<time datetime="${article.date}">${dateLabel(article.date)}</time></div><h3><a href="#/news/${article.id}">${article.title}</a></h3><p>${article.excerpt}</p></article>`;
export const featureCard = feature => `<article class="feature-card"><span class="feature-icon" aria-hidden="true">${feature.icon}</span><p class="eyebrow">${feature.label}</p><h3>${feature.title}</h3><p>${feature.text}</p></article>`;
export const notice = text => `<div class="notice"><span aria-hidden="true">ⓘ</span><p>${text}</p></div>`;
export function table(columns, rows) {
  return `<div class="table-scroll" tabindex="0" role="region" aria-label="Rankings table"><table><thead><tr>${columns.map(c => `<th scope="col">${c}</th>`).join('')}</tr></thead><tbody>${rows.length ? rows.map((row, i) => `<tr><td class="rank">${String(i + 1).padStart(2, '0')}</td>${row.map((cell, j) => `<td${j === 0 ? ' class="player-name"' : ''}>${escapeHtml(cell)}</td>`).join('')}</tr>`).join('') : `<tr><td colspan="${columns.length}" class="empty-state">No results match your search.</td></tr>`}</tbody></table></div>`;
}
